class ResidualDepthwiseBlock(nn.Module):

    def __init__(self, channels: int) -> None:
        super().__init__()
        self.grouped_spatial = nn.Conv2d(channels, channels, kernel_size=3, padding=1, groups=channels // 4, bias=False)
        self.norm1 = nn.BatchNorm2d(channels)
        self.pointwise = nn.Conv2d(channels, channels, kernel_size=1, bias=False)
        self.norm2 = nn.BatchNorm2d(channels)

    def forward(self, inputs: torch.Tensor) -> torch.Tensor:
        hidden = F.gelu(self.norm1(self.grouped_spatial(inputs)))
        hidden = self.norm2(self.pointwise(hidden))
        return F.gelu(inputs + hidden)

