    def forward(self, images: torch.Tensor) -> torch.Tensor:
        ema_params = getattr(self, '_ema_params', None)
        if not self.training and ema_params is not None and (not getattr(self, '_ema_active', False)):
            with torch.no_grad():
                for parameter, average in zip(self.parameters(), ema_params):
                    parameter.copy_(average)
            self._ema_active = True
        logits = self.classifier(self.features(images))
        if self.training:
            return logits
        padded = F.pad(images, (1, 1, 1, 1), mode='replicate')
