        view_weights = (36.0, 1.0, 6.0, 1.0, 6.0, 6.0, 1.0, 6.0, 1.0)
        log_probs = []
        for view, weight in zip(views, view_weights):
            log_weight = math.log(weight)
            log_probs.append(F.log_softmax(self.classifier(self.features(view)), dim=1) + log_weight)
            log_probs.append(F.log_softmax(self.classifier(self.features(view.flip(-1))), dim=1) + log_weight)
