        crop_weights = (3.0, 1.0, 1.0, 1.0, 1.0)
        for crop, weight in zip(crops, crop_weights):
            probabilities = probabilities + weight * F.softmax(self._forward_once(crop), dim=1)
            probabilities = probabilities + weight * F.softmax(self._forward_once(crop.flip(-1)), dim=1)
        probabilities = probabilities / (2.0 * sum(crop_weights))
        return probabilities.clamp_min(torch.finfo(probabilities.dtype).tiny).log() / 0.75317

