class ResidualContext(nn.Module):

    def __init__(self, channels: int, dilation: int) -> None:
        super().__init__()
        self.conv1 = nn.Conv2d(channels, channels, kernel_size=3, padding=dilation, dilation=dilation, bias=False, padding_mode='replicate')
        self.norm1 = nn.BatchNorm2d(channels)
        self.conv2 = nn.Conv2d(channels, channels, kernel_size=3, padding=dilation, dilation=dilation, bias=False, padding_mode='replicate')
        self.norm2 = nn.BatchNorm2d(channels)

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        residual = F.gelu(self.norm1(self.conv1(features)))
        residual = self.norm2(self.conv2(residual))
        return F.gelu(features + residual)

