class ImageClassifier(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        self.stem = nn.Sequential(nn.Conv2d(1, 16, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(16), nn.GELU(), nn.MaxPool2d(2), nn.Conv2d(16, 40, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(40), nn.GELU(), nn.MaxPool2d(2))
        self.residual = nn.Sequential(nn.Conv2d(40, 56, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(56), nn.GELU(), nn.Conv2d(56, 56, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(56))
        self.shortcut = nn.Sequential(nn.Conv2d(40, 56, kernel_size=1, bias=False), nn.BatchNorm2d(56))
        self.classifier = nn.Sequential(nn.Linear(2 * 56 * (1 + 4 + 16), 80), nn.GELU(), nn.LayerNorm(80), nn.Linear(80, 10))

    def _forward_once(self, images: torch.Tensor) -> torch.Tensor:
        features = self.stem(images)
        features = F.gelu(self.residual(features) + self.shortcut(features))
        pyramid = []
        for output_size in (1, 2, 4):
            pyramid.append(F.adaptive_avg_pool2d(features, output_size).flatten(1))
            pyramid.append(F.adaptive_max_pool2d(features, output_size).flatten(1))
        return self.classifier(torch.cat(pyramid, dim=1))

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        if self.training:
            return self._forward_once(images)
        padded = F.pad(images, (2, 2, 2, 2), mode='reflect')
        logits_sum = None
        central_logits_sum = None
        for offset_y in range(5):
            for offset_x in range(5):
                view = padded[:, :, offset_y:offset_y + 28, offset_x:offset_x + 28]
                views = torch.cat((view, view.flip(-1)), dim=0)
                logits = self._forward_once(views)
                original_logits, flipped_logits = logits.chunk(2, dim=0)
                view_logits = original_logits + flipped_logits
                if logits_sum is None:
                    logits_sum = view_logits
                else:
                    logits_sum = logits_sum + view_logits
                if 1 <= offset_y <= 3 and 1 <= offset_x <= 3:
                    central_weight = (2 if offset_y == 2 else 1) * (2 if offset_x == 2 else 1)
                    if central_logits_sum is None:
                        central_logits_sum = central_weight * view_logits
                    else:
                        central_logits_sum = central_logits_sum + central_weight * view_logits
        full_ensemble = logits_sum / 50.0
        central_ensemble = central_logits_sum / 32.0
        return 1.29834 * (0.9 * full_ensemble + 0.1 * central_ensemble)

