        for view in shifted_views:
            probability_sum.add_(F.softmax(self._forward_once(view), dim=1))
            probability_sum.add_(F.softmax(self._forward_once(view.flip(-1)), dim=1))
        return (probability_sum / 10.0).clamp_min(1e-08).log().mul_(1.05)

