        self.features = nn.Sequential(nn.Conv2d(5, 24, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(24), nn.GELU(), nn.MaxPool2d(2), nn.Conv2d(24, 48, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(48), nn.GELU(), nn.MaxPool2d(2), nn.Conv2d(48, 80, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(80), nn.GELU())
        self.refine = nn.Sequential(nn.Conv2d(80, 80, kernel_size=3, padding=1, groups=80, bias=False), nn.BatchNorm2d(80), nn.GELU(), nn.Conv2d(80, 80, kernel_size=1, bias=False), nn.BatchNorm2d(80))
        self.classifier = nn.Sequential(nn.Linear(80 * 2 * (1 + 4 + 16), 56), nn.LayerNorm(56), nn.GELU(), nn.Dropout(0.1), nn.Linear(56, 10))

    @staticmethod
    def _image_basis(images: torch.Tensor) -> torch.Tensor:
        padded = F.pad(images, (1, 1, 1, 1), mode='replicate')
        local_mean = F.avg_pool2d(padded, kernel_size=3, stride=1)
        local_contrast = images - local_mean
        gradient_x = 0.125 * (padded[:, :, :-2, 2:] + 2.0 * padded[:, :, 1:-1, 2:] + padded[:, :, 2:, 2:] - padded[:, :, :-2, :-2] - 2.0 * padded[:, :, 1:-1, :-2] - padded[:, :, 2:, :-2])
        gradient_y = 0.125 * (padded[:, :, 2:, :-2] + 2.0 * padded[:, :, 2:, 1:-1] + padded[:, :, 2:, 2:] - padded[:, :, :-2, :-2] - 2.0 * padded[:, :, :-2, 1:-1] - padded[:, :, :-2, 2:])
        edge_energy = torch.sqrt(gradient_x.square() + gradient_y.square() + 1e-06)
        return torch.cat((images, local_contrast, gradient_x, gradient_y, edge_energy), dim=1)

    @staticmethod
    def _spatial_pyramid(features: torch.Tensor) -> torch.Tensor:
        summaries = []
        for size in (1, 2, 4):
            summaries.append(F.adaptive_avg_pool2d(features, size).flatten(1))
            summaries.append(F.adaptive_max_pool2d(features, size).flatten(1))
        return torch.cat(summaries, dim=1)

    def _forward_once(self, images: torch.Tensor) -> torch.Tensor:
        features = self.features(self._image_basis(images))
        features = F.gelu(features + self.refine(features))
        return self.classifier(self._spatial_pyramid(features))

    def _flip_average(self, images: torch.Tensor) -> torch.Tensor:
        return 0.5 * (self._forward_once(images) + self._forward_once(images.flip(-1)))

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        if self.training:
            return self._forward_once(images)
        height, width = images.shape[-2:]
        padded = F.pad(images, (2, 2, 2, 2), mode='replicate')
        logits = 0.36 * self._flip_average(images)
        for delta_y in range(-2, 3):
