class SpatialRefinement(nn.Module):

    def __init__(self, channels: int) -> None:
        super().__init__()
        self.depthwise = nn.Sequential(nn.Conv2d(channels, channels, kernel_size=3, padding=1, groups=channels, bias=False), nn.BatchNorm2d(channels), nn.SiLU(inplace=True))
