    def forward(self, features: torch.Tensor) -> torch.Tensor:
        residual = self.project(self.depthwise(features))
        weights = self.attention(residual).view(residual.shape[0], residual.shape[1], 1, 1)
        return F.silu(features + residual * weights, inplace=True)

